from pathlib import Path
import re

ROOT = Path.cwd()
PUB = ROOT / "public"
VIEWS = ROOT / "views"
(PUB/"js").mkdir(parents=True, exist_ok=True)
(PUB/"css").mkdir(parents=True, exist_ok=True)
VIEWS.mkdir(exist_ok=True)


PROFILE_HTML = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>My profile — Nexora</title><link rel="stylesheet" href="/css/style.css"></head>\n<body class="dashboard-page"><aside class="sidebar"><a class="brand" href="/">NEXORA<span>.</span></a><div class="sidebar-label">YOUR ACCOUNT</div><a class="side-link" href="/user-dashboard">▦ &nbsp; Overview</a><a class="side-link selected" href="/profile">♙ &nbsp; My profile</a><a class="side-link" href="/about.html">ⓘ &nbsp; About Nexora</a><div class="sidebar-bottom"><div class="sidebar-help">Your personal details<small>Keep your account information up to date.</small></div><form action="/logout" method="POST"><button class="side-logout" type="submit">↪ &nbsp; Sign out</button></form></div></aside>\n<main class="dash-main"><header class="dash-top"><div><span class="eyebrow">ACCOUNT SETTINGS</span><h1>My profile</h1></div><div class="profile-top-actions"><button class="theme-toggle" type="button" aria-label="Toggle dark mode">☾</button><a class="text-link" href="/user-dashboard">← Back to dashboard</a></div></header>\n<section class="profile-hero"><div class="profile-avatar-large" id="profile-avatar">N</div><div><span class="eyebrow light">PERSONAL ACCOUNT</span><h2 id="profile-name-heading">Your profile</h2><p>Manage your personal information and account details.</p></div><span class="profile-role" id="profile-role">USER</span></section>\n<section class="content-card profile-content"><div class="card-heading"><div><span class="eyebrow">PERSONAL INFORMATION</span><h2>Your details</h2></div><span class="status-pill"><i></i> Account active</span></div>\n<div id="profile-message" class="inline-message" role="status" aria-live="polite"></div>\n<form id="profile-form" class="profile-form"><div class="profile-fields">\n<label>Full name<input name="name" id="profile-name" required maxlength="100"></label>\n<label>Email address<input name="email" id="profile-email" type="email" disabled><small>Email is your login identifier and cannot be edited here.</small></label>\n<label>Mobile number<input name="mobile" id="profile-mobile" type="tel" maxlength="20" placeholder="+91 98765 43210"></label>\n<label>College / Institution<input name="college" id="profile-college" maxlength="150" placeholder="Your college or institution"></label>\n<label>Account role<input id="profile-role-input" disabled></label>\n<label>Member since<input id="profile-created" disabled></label>\n</div><div class="profile-form-actions"><a class="btn btn-ghost" href="/user-dashboard">Cancel</a><button class="btn" type="submit">Save changes <span>→</span></button></div></form></section>\n<footer class="dash-footer">© <span data-year></span> Nexora <span>Your account, your details.</span></footer></main><script src="/js/profile.js"></script><script src="/js/site.js"></script></body></html>'
LOGIN_JS = 'document.addEventListener("DOMContentLoaded", () => {\n const form=document.getElementById("login-form"), msg=document.getElementById("login-error"), btn=document.getElementById("login-submit");\n if(!form||!msg||!btn)return;\n form.addEventListener("submit",async e=>{\n  e.preventDefault();msg.textContent="";msg.classList.remove("visible");btn.disabled=true;const original=btn.innerHTML;btn.textContent="Signing in…";\n  try{\n   const response=await fetch("/login",{method:"POST",body:new URLSearchParams(new FormData(form)),headers:{"Content-Type":"application/x-www-form-urlencoded"},credentials:"same-origin",redirect:"follow"});\n   if(response.redirected){window.location.assign(response.url);return;}\n   if(response.ok){window.location.assign(response.url||"/user-dashboard");return;}\n   let text="Incorrect email or password. Please try again.";\n   const ct=response.headers.get("content-type")||"";\n   if(ct.includes("application/json")){const data=await response.json();text=data.message||text;}\n   else if(response.status>=500)text="Something went wrong on the server. Please try again.";\n   msg.textContent=text;msg.classList.add("visible");\n  }catch(err){msg.textContent="Could not connect to the server. Please check your connection and try again.";msg.classList.add("visible");}\n  finally{btn.disabled=false;btn.innerHTML=original;}\n });\n});'
SITE_JS = 'document.addEventListener("DOMContentLoaded",()=>{\n document.querySelectorAll("[data-year]").forEach(el=>el.textContent=new Date().getFullYear());\n const toggle=document.querySelector(".menu-toggle"),nav=document.querySelector(".nav-links");\n if(toggle&&nav)toggle.addEventListener("click",()=>{const open=nav.classList.toggle("open");toggle.setAttribute("aria-expanded",String(open));});\n const buttons=document.querySelectorAll(".theme-toggle");\n const saved=localStorage.getItem("nexora-theme");\n const dark=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches;\n applyTheme(saved||(dark?"dark":"light"));\n buttons.forEach(btn=>btn.addEventListener("click",()=>{const next=document.documentElement.dataset.theme==="dark"?"light":"dark";localStorage.setItem("nexora-theme",next);applyTheme(next);}));\n function applyTheme(theme){document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;buttons.forEach(btn=>{btn.textContent=theme==="dark"?"☀":"☾";btn.setAttribute("aria-label",theme==="dark"?"Switch to light mode":"Switch to dark mode");btn.title=theme==="dark"?"Switch to light mode":"Switch to dark mode";});}\n});'
PROFILE_JS = 'document.addEventListener("DOMContentLoaded",async()=>{\n const get=id=>document.getElementById(id), msg=get("profile-message");\n const show=(text,ok=false)=>{msg.textContent=text;msg.classList.add("visible");msg.classList.toggle("success-message",ok);msg.classList.toggle("error-message",!ok);};\n try{\n  const r=await fetch("/api/profile",{credentials:"same-origin"});if(!r.ok){location.replace("/login.html");return;}const u=await r.json();\n  get("profile-name").value=u.name||"";get("profile-email").value=u.email||"";get("profile-mobile").value=u.mobile||"";get("profile-college").value=u.college||"";\n  get("profile-role-input").value=u.role||"";get("profile-role").textContent=(u.role||"user").toUpperCase();get("profile-name-heading").textContent=u.name||"Your profile";get("profile-avatar").textContent=(u.name||"N").trim().charAt(0).toUpperCase();\n  get("profile-created").value=u.created_at?new Date(u.created_at).toLocaleDateString():"—";\n }catch(e){show("Unable to load your profile. Please refresh.");}\n get("profile-form").addEventListener("submit",async e=>{\n  e.preventDefault();msg.classList.remove("visible");\n  const data={name:get("profile-name").value.trim(),mobile:get("profile-mobile").value.trim(),college:get("profile-college").value.trim()};\n  if(!data.name){show("Please enter your name.");return;}\n  try{const r=await fetch("/api/profile",{method:"PUT",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});const result=await r.json().catch(()=>({}));\n   if(!r.ok){show(result.message||"Could not save your profile.");return;}\n   get("profile-name-heading").textContent=data.name;get("profile-avatar").textContent=data.name.charAt(0).toUpperCase();show("Profile updated successfully.",true);\n  }catch(e){show("Could not connect to the server. Please try again.");}\n });\n});'
THEME_CSS = '\n/* Nexora theme switch + profile additions */\n.header-tools{display:flex;align-items:center;gap:12px}\n.theme-toggle{width:38px;height:38px;border-radius:9px;border:1px solid var(--line);background:var(--white);color:var(--ink);display:inline-grid;place-items:center;cursor:pointer;font-size:18px;transition:background .2s,border .2s}\n.theme-toggle:hover{border-color:var(--blue);background:var(--pale)}\n.dash-top .profile-top-actions{display:flex;align-items:center;gap:16px}\n.profile-link{cursor:pointer;transition:border .2s,transform .2s}.profile-link:hover{border-color:var(--blue);transform:translateY(-1px)}.profile-chevron{color:var(--blue);font-size:13px;margin-left:4px}\n.inline-message{display:none;padding:11px 13px;border-radius:8px;font-size:12px;line-height:1.5;margin:4px 0 10px}.inline-message.visible{display:block}.error-message{background:#fff1f2;border:1px solid #fecdd3;color:#be123c}.success-message{background:#effaf3;border:1px solid #bbf7d0;color:#15803d}\n#login-submit:disabled{opacity:.65;cursor:wait}\n.profile-hero{display:flex;align-items:center;gap:22px;background:var(--navy);color:white;padding:26px 30px;border-radius:13px;margin-bottom:22px}.profile-avatar-large{width:68px;height:68px;border-radius:50%;background:#e4efff;color:var(--blue);display:grid;place-items:center;font-size:27px;font-weight:850;flex-shrink:0}.profile-hero h2{font-size:24px;letter-spacing:-.7px;margin:5px 0}.profile-hero p{color:#c1ccdc;font-size:12px;margin:0}.profile-role{margin-left:auto;background:#e8f0ff;color:#245bd1;border-radius:20px;padding:6px 11px;font-size:9px;font-weight:850;letter-spacing:1px}.profile-content{padding:24px}.profile-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.profile-fields label{display:grid;gap:7px;color:#34435a;font-size:12px;font-weight:700}.profile-fields input{width:100%;border:1px solid #dce3ed;border-radius:7px;padding:12px;font:inherit;font-size:13px;color:var(--ink);background:white;outline:none}.profile-fields input:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(37,99,235,.1)}.profile-fields input:disabled{background:#f5f7fb;color:#8793a5}.profile-fields small{font-weight:400;font-size:10px;color:#8793a5}.profile-form-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:24px}.btn-ghost{background:white;color:var(--ink);border-color:var(--line);box-shadow:none}.btn-ghost:hover{background:#f7f9fc;color:var(--ink)}\n/* Dark theme variables are applied to all pages that load the common stylesheet. */\nhtml[data-theme="dark"]{--navy:#e7eefc;--blue:#7ba8ff;--blue-dark:#5c8df0;--ink:#e7eefc;--muted:#a6b4c9;--line:#2b3a52;--pale:#1b2b45;--bg:#0b1220;--white:#111c2e;--shadow:0 18px 55px rgba(0,0,0,.28);color-scheme:dark}\nhtml[data-theme="dark"] body{background:#0b1220;color:var(--ink)}\nhtml[data-theme="dark"] .site-header,html[data-theme="dark"] .site-footer{background:#0b1220}\nhtml[data-theme="dark"] .brand{color:#e7eefc}\nhtml[data-theme="dark"] .nav-links{color:#a6b4c9}\nhtml[data-theme="dark"] .nav-links.open{background:#111c2e;border-color:#2b3a52}\nhtml[data-theme="dark"] .hero h1,html[data-theme="dark"] .page-hero h1,html[data-theme="dark"] .section-heading h2,html[data-theme="dark"] .about-copy>h2{color:#e7eefc}\nhtml[data-theme="dark"] .features,html[data-theme="dark"] .auth-page,html[data-theme="dark"] .dashboard-page{background:#0b1220}\nhtml[data-theme="dark"] .feature-card,html[data-theme="dark"] .auth-card,html[data-theme="dark"] .sidebar,html[data-theme="dark"] .dash-card,html[data-theme="dark"] .content-card,html[data-theme="dark"] .profile-chip{background:#111c2e;border-color:#2b3a52;color:#e7eefc}\nhtml[data-theme="dark"] .feature-card h3,html[data-theme="dark"] .dash-card strong,html[data-theme="dark"] .card-heading h2,html[data-theme="dark"] .auth-card h2,html[data-theme="dark"] .profile-chip b{color:#e7eefc}\nhtml[data-theme="dark"] .page-hero{background:linear-gradient(180deg,#101d32,#0b1220)}\nhtml[data-theme="dark"] .form-stack label,html[data-theme="dark"] .profile-fields label{color:#c7d3e5}\nhtml[data-theme="dark"] .form-stack input,html[data-theme="dark"] .profile-fields input{background:#0b1220;border-color:#2b3a52;color:#e7eefc}\nhtml[data-theme="dark"] .profile-fields input:disabled{background:#17243a;color:#8c9cb5}\nhtml[data-theme="dark"] .profile-fields input::placeholder{color:#71829b}\nhtml[data-theme="dark"] .side-link{color:#a6b4c9}\nhtml[data-theme="dark"] .side-link:hover,html[data-theme="dark"] .side-link.selected{background:#1b2b45;color:#7ba8ff}\nhtml[data-theme="dark"] .sidebar-help{background:#17243a;color:#e7eefc}\nhtml[data-theme="dark"] .mock-window,html[data-theme="dark"] .float-card{background:#111c2e;border-color:#2b3a52}\nhtml[data-theme="dark"] .mock-top,html[data-theme="dark"] .mock-sidebar{border-color:#2b3a52}\nhtml[data-theme="dark"] .mock-main h3,html[data-theme="dark"] .float-card b{color:#e7eefc}\nhtml[data-theme="dark"] .mock-stats>div{border-color:#2b3a52}\nhtml[data-theme="dark"] .mock-stats strong{color:#e7eefc}\nhtml[data-theme="dark"] th{background:#17243a;color:#9eafc7}\nhtml[data-theme="dark"] td{border-color:#2b3a52;color:#b9c6d8}\nhtml[data-theme="dark"] td:first-child{color:#e7eefc}\nhtml[data-theme="dark"] .btn-ghost{background:#111c2e;color:#e7eefc;border-color:#2b3a52}\nhtml[data-theme="dark"] .theme-toggle{background:#111c2e;color:#e7eefc;border-color:#2b3a52}\nhtml[data-theme="dark"] .error-message{background:#351a27;border-color:#713044;color:#ffb4c5}\nhtml[data-theme="dark"] .success-message{background:#123023;border-color:#245c40;color:#9de4b8}\n@media(max-width:650px){.profile-fields{grid-template-columns:1fr}.profile-hero{padding:20px;gap:13px}.profile-avatar-large{width:50px;height:50px;font-size:20px}.profile-hero h2{font-size:20px}.profile-role{padding:5px 8px}.profile-form-actions{flex-wrap:wrap}.dash-top .profile-top-actions{gap:8px;flex-wrap:wrap;justify-content:flex-end}}\n'

# Login form changes: inline feedback and fetch submit (avoids browser blank error page).
login = PUB/"login.html"
if login.exists():
    html=login.read_text(encoding="utf-8")
    html=html.replace('<form action="/login" method="POST" class="form-stack">','<form action="/login" method="POST" class="form-stack" id="login-form">')
    html=html.replace('<button class="btn btn-full" type="submit">Sign in <span>→</span></button>',
      '<div id="login-error" class="inline-message error-message" role="alert" aria-live="polite"></div><button class="btn btn-full" type="submit" id="login-submit">Sign in <span>→</span></button>')
    if '/js/login.js' not in html:
        html=html.replace('<script src="/js/site.js"></script>','<script src="/js/login.js"></script><script src="/js/site.js"></script>')
    login.write_text(html,encoding="utf-8")

# Dashboard profile chips become links; add theme control.
for file in ["user-dashboard.html","admin-dashboard.html"]:
    p=VIEWS/file
    if not p.exists(): continue
    html=p.read_text(encoding="utf-8")
    html=html.replace('<div class="profile-chip"><span class="avatar"',
      '<a class="profile-chip profile-link" href="/profile" title="Open profile"><span class="avatar"')
    html=html.replace('</small></div></div></header>',
      '</small></div><span class="profile-chevron">↗</span></a><button class="theme-toggle dash-theme" type="button" aria-label="Toggle dark mode" title="Toggle dark mode">☾</button></div></header>')
    p.write_text(html,encoding="utf-8")

# Profile page.
(VIEWS/"profile.html").write_text(PROFILE_HTML,encoding="utf-8")
(PUB/"js/login.js").write_text(LOGIN_JS,encoding="utf-8")
(PUB/"js/site.js").write_text(SITE_JS,encoding="utf-8")
(PUB/"js/profile.js").write_text(PROFILE_JS,encoding="utf-8")
with (PUB/"css/style.css").open("a",encoding="utf-8") as f:
    f.write("\n"+THEME_CSS)

print("Nexora feature upgrade files installed. Review README-UPGRADE.txt and apply server/database changes.")
